"""Patient-level insights generated by the twin and mined from the record.

* personal_glycaemic_index() - how THIS patient's physiology responds to every
  food in the Indian library (simulated on the twin, not a population table).
* clinical_brief()           - patterns mined from the observed CGM, meal, sleep,
  activity and medication history, written as a short clinician summary.
"""
import numpy as np

from .. import physiology as phys
from ..config import DAY, CGM_STEP, CALIB_DAYS, NAVRATRI_DAYS, SPIKE_MGDL
from ..foods import FOODS


def personal_glycaemic_index(twin, t, tod=13 * 60, H=240):
    """Simulate one standard serving of each food at lunchtime from a fasting
    steady state using today's adaptive twin parameters."""
    foods = list(FOODS)
    B = len(foods)
    p = twin.params_at([t] * B)
    st = phys.steady_state(p)
    inp = phys.empty_inputs(B, H)
    for i, f in enumerate(foods):
        info = FOODS[f]
        inp["carbs_fast"][i, 0] = info["carbs"] * info["fast"]
        inp["carbs_slow"][i, 0] = info["carbs"] * (1 - info["fast"])
    G, _, _ = phys.simulate(p, st, inp, tod0=np.full(B, tod))
    base = G[:, 0:1]
    rise = (G - base).max(1)
    auc = np.clip(G - base, 0, None).sum(1) / 60.0              # mg/dL·h
    ref = rise[foods.index("rice_dal_thali")]
    out = []
    for i, f in enumerate(foods):
        info = FOODS[f]
        out.append(dict(food=f, name=info["name"], hi=info["hi"], icon=info["icon"], carbs=info["carbs"],
                        slot=info["slot"], rise=round(float(rise[i]), 1), auc=round(float(auc[i]), 1),
                        peak=round(float(G[i].max()), 1), t_peak=int(G[i].argmax()),
                        rel=round(float(rise[i] / ref * 100), 0),
                        curve=np.round(G[i, ::10], 1).tolist()))
    out.sort(key=lambda r: -r["rise"])
    return dict(foods=out, reference="rice_dal_thali", tod=tod)


def _post_meal_rise(cg5, minute):
    e = minute // CGM_STEP
    pre = cg5[max(0, e - 2):e + 1]
    post = cg5[e + 6:e + 30]
    if np.all(np.isnan(pre)) or np.sum(~np.isnan(post)) < 12:
        return None
    return float(np.nanmax(post) - np.nanmean(pre))


def clinical_brief(twin, t):
    r = twin.rec
    cg5 = r.wear["cgm_mgdl"].values.astype(float)
    st5 = r.wear["steps"].values.astype(float)
    e_now = t // CGM_STEP
    meals = r.meals[r.meals["minute"] <= t - 150]
    rows = []
    for m in meals.itertuples():
        rise = _post_meal_rise(cg5, int(m.minute))
        if rise is None:
            continue
        e = int(m.minute) // CGM_STEP
        walk = st5[e + 2:e + 9].sum()                       # steps 10-45 min after the meal
        rows.append(dict(food=m.food_id, kind=m.meal_type, minute=int(m.minute), rise=rise, carbs=m.carbs_g_est,
                         walk=walk, late=(m.minute % DAY) >= 21.5 * 60, fasting=FOODS.get(m.food_id, {}).get("slot") == "fast"))
    findings = []

    def add(sev, title, detail, metric=None, kind="pattern"):
        findings.append(dict(severity=sev, title=title, detail=detail, metric=metric, kind=kind))

    if rows:
        by_food = {}
        for x in rows:
            by_food.setdefault(x["food"], []).append(x["rise"])
        ranked = sorted(((np.mean(v), k, len(v)) for k, v in by_food.items() if len(v) >= 2), reverse=True)
        if ranked:
            mu, k, n = ranked[0]
            add("high" if mu > 80 else "medium", f"Biggest observed spike: {FOODS[k]['name']}",
                f"Average rise of {mu:.0f} mg/dL across {n} meals. Prioritise this meal for swaps.", f"+{mu:.0f}")
        main = [x for x in rows if x["kind"] in ("lunch", "dinner", "breakfast") and x["carbs"] >= 35]
        walked = [x["rise"] for x in main if x["walk"] >= 600]
        sat = [x["rise"] for x in main if x["walk"] < 150]
        if len(walked) >= 2 and len(sat) >= 2 and np.mean(sat) - np.mean(walked) > 5:
            d = np.mean(sat) - np.mean(walked)
            add("good" if d > 0 else "info", "Post-meal walks work for this patient" if d > 0 else "Post-meal walks: no clear effect yet",
                f"After meals followed by a walk, the rise was {np.mean(walked):.0f} mg/dL vs {np.mean(sat):.0f} when sedentary "
                f"({len(walked)} vs {len(sat)} meals).", f"−{d:.0f}" if d > 0 else None)
        late = [x["rise"] for x in rows if x["kind"] == "dinner" and x["late"]]
        early = [x["rise"] for x in rows if x["kind"] == "dinner" and not x["late"]]
        if len(late) >= 2 and len(early) >= 2 and np.mean(late) - np.mean(early) > 8:
            add("medium", "Late dinners raise excursions",
                f"Dinners after 21:30 rose {np.mean(late):.0f} mg/dL vs {np.mean(early):.0f} for earlier dinners.",
                f"+{np.mean(late) - np.mean(early):.0f}")
        fast = [x["rise"] for x in rows if x["fasting"] and x["kind"] in ("lunch", "dinner")]
        norm = [x["rise"] for x in rows if not x["fasting"] and x["kind"] in ("lunch", "dinner")]
        if len(fast) >= 2 and norm and np.mean(fast) - np.mean(norm) > 8:
            add("high", "Navratri fasting meals spike harder",
                f"Fasting foods (sabudana, kuttu, sweets) rose {np.mean(fast):.0f} mg/dL vs {np.mean(norm):.0f} for usual meals. "
                f"Suggest fruit, makhana or a smaller portion paired with curd.", f"+{np.mean(fast) - np.mean(norm):.0f}")

    # sleep -> next-day glucose
    day_now = t // DAY
    by_day = {}
    for d in range(CALIB_DAYS - 2, day_now):
        c = cg5[d * 288:(d + 1) * 288]
        if np.sum(~np.isnan(c)) > 150:
            by_day[d] = float(np.nanmean(c))
    nights = {n["day"]: n["hours"] for n in r.nights}
    short = [by_day[d] for d in by_day if d in nights and nights[d] < 6.0]
    ok = [by_day[d] for d in by_day if d in nights and nights[d] >= 6.5]
    if len(short) >= 2 and len(ok) >= 2:
        diff = np.mean(short) - np.mean(ok)
        if diff > 3:
            add("medium", "Short sleep raises next-day glucose",
                f"After nights under 6 h, mean glucose was {np.mean(short):.0f} vs {np.mean(ok):.0f} mg/dL after 6.5 h or more.", f"+{diff:.0f}")
    # dawn phenomenon
    dawn = []
    for d in range(1, day_now + 1):
        a, b = cg5[d * 288 + 36:d * 288 + 42], cg5[d * 288 + 90:d * 288 + 96]   # 03:00 vs 07:30
        if np.sum(~np.isnan(a)) > 2 and np.sum(~np.isnan(b)) > 2:
            dawn.append(np.nanmean(b) - np.nanmean(a))
    if len(dawn) >= 3 and np.mean(dawn) > 8:
        add("info", "Dawn phenomenon detected",
            f"Glucose climbs by about {np.mean(dawn):.0f} mg/dL between 03:00 and 07:30 without food. "
            f"The twin has learned a dawn amplitude of {twin.params.get('dawn', 0):.2f} mg/dL/min.", f"+{np.mean(dawn):.0f}")
    # adherence
    md = r.meds[r.meds["minute"] <= t]
    if len(md):
        rate = md["taken"].mean() * 100
        if rate < 90:
            add("medium" if rate > 75 else "high", f"Metformin adherence {rate:.0f}%",
                f"{int((~md['taken'].astype(bool)).sum())} of {len(md)} logged doses were missed. Missed doses raise the twin's hepatic set-point.",
                f"{rate:.0f}%")
    # adaptive twin drift
    si_now = float(twin.si_mult[t])
    if abs(si_now - 1) >= 0.05:
        add("info", "Insulin sensitivity is drifting",
            f"The adaptive twin estimates today's insulin sensitivity at {si_now * 100:.0f}% of the onboarding baseline.",
            f"{(si_now - 1) * 100:+.0f}%", kind="twin")
    # glycaemic summary
    c = cg5[:e_now + 1]
    c = c[~np.isnan(c)]
    tir = float(np.mean((c >= 70) & (c <= 180)) * 100)
    order = dict(high=0, medium=1, info=2, good=3)
    findings.sort(key=lambda f: order[f["severity"]])
    headline = (f"Time in range {tir:.0f}% ({'meets' if tir >= 70 else 'below'} the 70% target). "
                f"{sum(f['severity'] == 'high' for f in findings)} high-priority pattern(s) found.")
    return dict(headline=headline, findings=findings, n_meals_analysed=len(rows))
